(242,'theme_boost','scss','.crisol-hero { background: linear-gradient(135deg, #1e293b 0%, #0f172a 100%); color: #fff; padding: 40px 20px; border-radius: 12px; margin-bottom: 30px; } .crisol-hero h1 { color: #f8fafc; font-size: 2.2rem; font-weight: 700; margin-bottom: 10px; } .crisol-hero p { color: #94a3b8; font-size: 1.1rem; margin-bottom: 20px; } .crisol-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 20px; margin-top: 20px; } .crisol-card { background: #ffffff; border: 1px solid #e2e8f0; border-radius: 10px; padding: 20px; box-shadow: 0 4px 6px -1px rgba(0,0,0,0.1); transition: transform 0.2s; } .crisol-card:hover { transform: translateY(-4px); } .crisol-card h3 { color: #0f172a; font-size: 1.25rem; font-weight: 600; margin-top: 10px; } .crisol-card p { color: #64748b; font-size: 0.95rem; } .crisol-card-badge { display: flex; justify-content: space-between; font-size: 0.8rem; font-weight: 600; color: #6366f1; text-transform: uppercase; } .crisol-card-btn { display: inline-block; margin-top: 15px; padding: 8px 16px; background: #6366f1; color: #ffffff !important; border-radius: 6px; text-decoration: none; font-weight: 500; font-size: 0.9rem; } .crisol-card-btn:hover { background: #4f46e5; text-decoration: none; } .crisol-seminarios-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 15px; margin-top: 20px; } .crisol-seminario-card { background: #f8fafc; border-left: 4px solid #8b5cf6; padding: 16px; border-radius: 6px; } .crisol-seminario-card h3 { font-size: 1.1rem; color: #1e293b; margin-top: 5px; }'),
