(2087,'theme_boost','customcss','\\n/* =========================================================\\n   LOGIN CRISOL CIENCIAS ÓNTICAS - STYLING ACCORDING TO REFERENCE\\n   ========================================================= */\\n\\nbody.crisol-login-page, body#page-login-index {\\n  background-color: #000000 !important;\\n  color: #ffffff !important;\\n  margin: 0 !important;\\n  padding: 0 !important;\\n  font-family: system-ui, -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, sans-serif !important;\\n  min-height: 100vh !important;\\n  overflow-x: hidden !important;\\n}\\n\\n#page-login-index #page-wrapper, .crisol-login-bg {\\n  background: url(\'/pix/crisol_moodle_login_bg.jpg\') center bottom / cover no-repeat fixed !important;\\n  min-height: 100vh !important;\\n  display: flex !important;\\n  flex-direction: column !important;\\n  justify-content: space-between !important;\\n  padding: 0 !important;\\n  margin: 0 !important;\\n}\\n\\n#page-login-index #page, #page-login-index #page-content, #page-login-index #region-main-box, #page-login-index #region-main {\\n  background: transparent !important;\\n  border: none !important;\\n  box-shadow: none !important;\\n  padding: 0 !important;\\n  margin: 0 !important;\\n}\\n\\n/* Header Topbar */\\n.crisol-login-topbar {\\n  display: flex !important;\\n  justify-content: space-between !important;\\n  align-items: center !important;\\n  padding: 1.5rem 2.5rem !important;\\n  width: 100% !important;\\n  box-sizing: border-box !important;\\n}\\n\\n.crisol-logo-head {\\n  height: 52px !important;\\n  width: auto !important;\\n  object-fit: contain !important;\\n}\\n\\n.crisol-globe-icon {\\n  font-size: 1.25rem !important;\\n  color: #ff5722 !important;\\n  cursor: pointer !important;\\n  opacity: 0.9 !important;\\n  transition: opacity 0.2s !important;\\n}\\n.crisol-globe-icon:hover {\\n  opacity: 1 !important;\\n}\\n\\n/* Content Container & Grid Layout */\\n.crisol-login-content-container {\\n  max-width: 1280px !important;\\n  margin: 0 auto !important;\\n  width: 100% !important;\\n  padding: 2rem 3rem 6rem 3rem !important;\\n  flex: 1 !important;\\n  display: flex !important;\\n  align-items: flex-start !important;\\n  box-sizing: border-box !important;\\n}\\n\\n.crisol-login-grid {\\n  display: grid !important;\\n  grid-template-columns: 1fr 340px !important;\\n  gap: 3rem !important;\\n  width: 100% !important;\\n  align-items: flex-start !important;\\n}\\n\\n/* Hero Title on Left */\\n.crisol-login-hero-text {\\n  padding-top: 1rem !important;\\n}\\n\\n.crisol-main-title {\\n  font-size: 2.6rem !important;\\n  font-weight: 400 !important;\\n  color: #ffffff !important;\\n  line-height: 1.25 !important;\\n  letter-spacing: -0.01em !important;\\n  margin-bottom: 2rem !important;\\n  max-width: 600px !important;\\n}\\n\\n.crisol-welcome-sub {\\n  font-size: 2rem !important;\\n  font-weight: 400 !important;\\n  color: #ffffff !important;\\n  margin: 0 !important;\\n}\\n\\n/* Right Login Form Container */\\n.crisol-login-card {\\n  background: transparent !important;\\n  border: none !important;\\n  padding: 0 !important;\\n  box-shadow: none !important;\\n  width: 100% !important;\\n  max-width: 340px !important;\\n  margin-left: auto !important;\\n}\\n\\n#page-login-index .loginform {\\n  background: transparent !important;\\n  border: none !important;\\n  padding: 0 !important;\\n  box-shadow: none !important;\\n}\\n\\n#page-login-index .login-heading,\\n#page-login-index .login-divider,\\n#page-login-index #guestlogin,\\n#page-login-index .d-flex:has(.login-languagemenu),\\n#page-login-index button[data-modal=\"alert\"] {\\n  display: none !important;\\n}\\n\\n/* Form Labels */\\n#page-login-index label,\\n#page-login-index label[for=\"username\"],\\n#page-login-index label[for=\"password\"] {\\n  display: block !important;\\n  color: #ffffff !important;\\n  font-size: 0.925rem !important;\\n  font-weight: 400 !important;\\n  margin-bottom: 0.35rem !important;\\n  letter-spacing: 0.01em !important;\\n}\\n\\n/* Input Fields with Prefix Icons */\\n#page-login-index .login-form-username,\\n#page-login-index .login-form-password {\\n  position: relative !important;\\n  margin-bottom: 1.25rem !important;\\n}\\n\\n#page-login-index .login-form-username::before {\\n  content: \"✉\" !important;\\n  position: absolute !important;\\n  left: 0 !important;\\n  bottom: 0 !important;\\n  height: 42px !important;\\n  width: 42px !important;\\n  background: #d1d5db !important;\\n  color: #374151 !important;\\n  display: flex !important;\\n  align-items: center !important;\\n  justify-content: center !important;\\n  font-size: 15px !important;\\n  border-top-left-radius: 4px !important;\\n  border-bottom-left-radius: 4px !important;\\n  border-right: 1px solid #cbd5e1 !important;\\n  z-index: 2 !important;\\n  pointer-events: none !important;\\n}\\n\\n#page-login-index .login-form-password::before {\\n  content: \"🔒\" !important;\\n  position: absolute !important;\\n  left: 0 !important;\\n  bottom: 0 !important;\\n  height: 42px !important;\\n  width: 42px !important;\\n  background: #d1d5db !important;\\n  color: #374151 !important;\\n  display: flex !important;\\n  align-items: center !important;\\n  justify-content: center !important;\\n  font-size: 14px !important;\\n  border-top-left-radius: 4px !important;\\n  border-bottom-left-radius: 4px !important;\\n  border-right: 1px solid #cbd5e1 !important;\\n  z-index: 2 !important;\\n  pointer-events: none !important;\\n}\\n\\n#page-login-index #username,\\n#page-login-index #password {\\n  height: 42px !important;\\n  background-color: #f1f5f9 !important;\\n  color: #0f172a !important;\\n  border: 1px solid #cbd5e1 !important;\\n  border-radius: 4px !important;\\n  padding: 0.5rem 0.75rem 0.5rem 50px !important;\\n  font-size: 0.95rem !important;\\n  width: 100% !important;\\n  box-sizing: border-box !important;\\n  outline: none !important;\\n  box-shadow: none !important;\\n}\\n\\n#page-login-index #username::placeholder,\\n#page-login-index #password::placeholder {\\n  color: #64748b !important;\\n  opacity: 0.9 !important;\\n}\\n\\n#page-login-index #username:focus,\\n#page-login-index #password:focus {\\n  background-color: #ffffff !important;\\n  border-color: #94a3b8 !important;\\n}\\n\\n/* Submit Button - Orange Pill matching reference image */\\n#page-login-index .login-form-submit {\\n  margin-top: 1rem !important;\\n  text-align: left !important;\\n}\\n\\n#page-login-index #loginbtn {\\n  background: #e65100 !important;\\n  border: none !important;\\n  color: #ffffff !important;\\n  font-weight: 500 !important;\\n  font-size: 0.925rem !important;\\n  padding: 0.45rem 1.6rem !important;\\n  border-radius: 10px !important;\\n  width: auto !important;\\n  min-width: 110px !important;\\n  display: inline-block !important;\\n  cursor: pointer !important;\\n  box-shadow: 0 4px 12px rgba(230, 81, 0, 0.35) !important;\\n  transition: all 0.2s ease !important;\\n}\\n\\n#page-login-index #loginbtn:hover {\\n  background: #ff5722 !important;\\n  box-shadow: 0 6px 16px rgba(255, 87, 34, 0.45) !important;\\n}\\n\\n#page-login-index .login-form-forgotpassword {\\n  margin-top: 1rem !important;\\n}\\n\\n#page-login-index .login-form-forgotpassword a {\\n  color: #94a3b8 !important;\\n  font-size: 0.85rem !important;\\n  text-decoration: none !important;\\n}\\n#page-login-index .login-form-forgotpassword a:hover {\\n  color: #f8fafc !important;\\n  text-decoration: underline !important;\\n}\\n\\n/* Responsive */\\n@media (max-width: 900px) {\\n  .crisol-login-grid {\\n    grid-template-columns: 1fr !important;\\n    gap: 2rem !important;\\n  }\\n  .crisol-login-card {\\n    margin-left: 0 !important;\\n    max-width: 100% !important;\\n  }\\n  .crisol-main-title {\\n    font-size: 2rem !important;\\n  }\\n}\\n'),
